import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import { getMatchId, getLeagueTable } from "../api"; // Добавь getLeagueTable в api.js

function MatchDetailPage() {
  const { matchId } = useParams();
  const [match, setMatch] = useState(null);
  const [table, setTable] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      const matchData = await getMatchId(matchId);
      setMatch(matchData);

      if (matchData && matchData.league) {
        const tableData = await getLeagueTable(matchData.league);
        setTable(tableData);
      }
      setLoading(false);
    };
    fetchData();
  }, [matchId]);

  if (loading)
    return (
      <div className="flex justify-center items-center h-screen animate-pulse text-gray-500 uppercase font-black">
        Neural Analysis in Progress...
      </div>
    );
  if (!match)
    return (
      <div className="text-center py-20 text-red-500 font-bold">
        Матч не найден.
      </div>
    );

  const predStyle = (outcome) => {
    if (outcome === "Win Home")
      return {
        text: "Победа П1",
        color: "text-green-500",
        border: "border-green-500",
      };
    if (outcome === "Win Away")
      return {
        text: "Победа П2",
        color: "text-red-500",
        border: "border-red-500",
      };
    return {
      text: "Ничья X",
      color: "text-yellow-500",
      border: "border-yellow-500",
    };
  };

  const style = predStyle(match.prediction?.outcome);

  return (
    <div className="flex flex-col lg:flex-row gap-6 lg:gap-8 max-w-7xl mx-auto px-4 py-6">
      <section className="w-full lg:flex-grow">
        {/* 1. ШАПКА МАТЧА */}
        <div className="bg-gray-900 rounded-3xl p-8 mb-6 border border-gray-800 shadow-2xl">
          <div className="flex justify-between items-center text-center">
            <div className="w-2/5 flex flex-col items-center">
              <img
                src={match.homeTeam.logo_url}
                className="h-24 w-24 md:h-36 md:w-36 object-contain mb-4"
                alt=""
              />
              <h2 className="text-xl md:text-2xl font-black text-white uppercase tracking-tighter">
                {match.homeTeam.name_ru || match.homeTeam.name}
              </h2>
              <span className="mt-2 text-[10px] bg-gray-800 px-3 py-1 rounded-full text-yellow-500 font-mono">
                ELO: {Math.round(match.homeTeam.elo)}
              </span>
            </div>

            <div className="flex flex-col items-center">
              <span className="text-4xl font-black text-gray-800 italic">
                VS
              </span>
              <div className="text-xs text-gray-500 mt-2 font-bold uppercase tracking-widest">
                {new Date(match.utcDate).toLocaleTimeString([], {
                  hour: "2-digit",
                  minute: "2-digit",
                })}
              </div>
            </div>

            <div className="w-2/5 flex flex-col items-center">
              <img
                src={match.awayTeam.logo_url}
                className="h-24 w-24 md:h-36 md:w-36 object-contain mb-4"
                alt=""
              />
              <h2 className="text-xl md:text-2xl font-black text-white uppercase tracking-tighter">
                {match.awayTeam.name_ru || match.awayTeam.name}
              </h2>
              <span className="mt-2 text-[10px] bg-gray-800 px-3 py-1 rounded-full text-yellow-500 font-mono">
                ELO: {Math.round(match.awayTeam.elo)}
              </span>
            </div>
          </div>
        </div>

        {/* 2. БЛОК ПРОГНОЗА */}
        {match.prediction && (
          <div
            className={`bg-gray-900 rounded-3xl p-8 mb-6 border-l-8 ${style.border} shadow-2xl`}
          >
            <div className="grid grid-cols-1 md:grid-cols-3 gap-8 items-center">
              {/* Исход */}
              <div className="text-center md:text-left">
                <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest block mb-2">
                  Прогноз исхода
                </span>
                <span
                  className={`text-2xl font-black uppercase ${style.color}`}
                >
                  {style.text}
                </span>
                <div className="mt-4 flex gap-1 h-1.5 w-full bg-gray-800 rounded-full overflow-hidden">
                  <div
                    className="bg-green-500 h-full"
                    style={{ width: `${match.prediction.prob_home}%` }}
                  ></div>
                  <div
                    className="bg-yellow-500 h-full"
                    style={{ width: `${match.prediction.prob_draw}%` }}
                  ></div>
                  <div
                    className="bg-red-500 h-full"
                    style={{ width: `${match.prediction.prob_away}%` }}
                  ></div>
                </div>
              </div>

              {/* Точный счет */}
              <div className="text-center bg-black/20 py-4 rounded-2xl border border-white/5">
                <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest block mb-1">
                  Ожидаемый счет
                </span>
                <span className="text-4xl font-black text-white tracking-widest italic">
                  {match.prediction.exact_score}
                </span>
              </div>

              {/* Тотал (УКРУПНЕН) */}
              <div className="text-center md:text-right">
                <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest block mb-2">
                  Результативность
                </span>
                <div className="inline-block bg-blue-600/20 border border-blue-500/50 px-6 py-2 rounded-xl">
                  <span className="text-blue-400 font-black text-lg">
                    ТБ 2.5: {match.prediction.total_over_2_5}%
                  </span>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* 3. СРАВНИТЕЛЬНАЯ СТАТИСТИКА */}
        <div className="bg-gray-900 rounded-3xl p-8 border border-gray-800 shadow-2xl">
          <h3 className="text-xs font-black text-gray-500 uppercase tracking-[0.3em] mb-10 text-center">
            Глубокий анализ показателей (Last 5)
          </h3>
          <div className="space-y-8">
            <StatRow
              label="Ожидаемые голы (xG)"
              home={match.homeTeam.stats_last_5?.xg}
              away={match.awayTeam.stats_last_5?.xg}
            />
            <StatRow
              label="Прессинг (PPDA)"
              home={match.homeTeam.stats_last_5?.ppda}
              away={match.awayTeam.stats_last_5?.ppda}
              reverse
            />
            <StatRow
              label="Опасные атаки (Deep)"
              home={match.homeTeam.stats_last_5?.deep}
              away={match.awayTeam.stats_last_5?.deep}
            />
          </div>
        </div>
      </section>

      {/* 4. САЙДБАР: ТУРНИРНАЯ ТАБЛИЦА (РАБОЧАЯ) */}
      <aside className="w-full lg:w-80 flex-shrink-0">
        <div className="bg-gray-900 p-6 rounded-3xl border border-gray-800 sticky top-28 shadow-2xl">
          <h3 className="text-xs font-black text-gray-500 uppercase tracking-widest mb-6">
            Championship Table
          </h3>
          <div className="overflow-hidden">
            <table className="w-full text-left text-[11px]">
              <thead>
                <tr className="text-gray-600 border-b border-gray-800">
                  <th className="pb-3 font-bold">#</th>
                  <th className="pb-3 font-bold">Team</th>
                  <th className="pb-3 font-bold text-center">M</th>
                  <th className="pb-3 font-bold text-right text-white">PTS</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-800/50">
                {table.length > 0 ? (
                  table.map((row, idx) => (
                    <tr
                      key={idx}
                      className={`hover:bg-white/5 transition-colors ${row.team === match.homeTeam.name || row.team === match.awayTeam.name ? "bg-red-600/10" : ""}`}
                    >
                      <td className="py-2.5 text-gray-500 font-mono">
                        {idx + 1}
                      </td>
                      <td className="py-2.5 font-bold text-gray-300 truncate max-w-[100px]">
                        {row.team}
                      </td>
                      <td className="py-2.5 text-center text-gray-500">
                        {row.M}
                      </td>
                      <td className="py-2.5 text-right font-black text-white">
                        {row.PTS}
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td
                      colSpan="4"
                      className="py-10 text-center text-gray-700 italic font-bold uppercase tracking-widest"
                    >
                      Loading Table...
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </aside>
    </div>
  );
}

const StatRow = ({ label, home, away, reverse = false }) => {
  const h = parseFloat(home) || 0;
  const a = parseFloat(away) || 0;
  const isHomeBetter = reverse ? h < a : h > a;

  return (
    <div className="group">
      <div className="flex justify-between mb-3 px-1 items-end">
        <div className="flex flex-col">
          <span
            className={`text-xl font-black ${isHomeBetter ? "text-white" : "text-gray-600"}`}
          >
            {h.toFixed(2)}
          </span>
        </div>
        <span className="text-[9px] text-gray-500 uppercase font-black tracking-widest pb-1">
          {label}
        </span>
        <div className="flex flex-col items-end">
          <span
            className={`text-xl font-black ${!isHomeBetter ? "text-white" : "text-gray-600"}`}
          >
            {a.toFixed(2)}
          </span>
        </div>
      </div>
      <div className="flex w-full h-2 bg-gray-800 rounded-full overflow-hidden p-0.5 border border-gray-700">
        <div
          className={`h-full rounded-full transition-all duration-700 ${isHomeBetter ? "bg-green-500 shadow-[0_0_10px_green]" : "bg-gray-700"}`}
          style={{ width: `${(h / (h + a)) * 100}%` }}
        ></div>
        <div
          className={`h-full rounded-full transition-all duration-700 ${!isHomeBetter ? "bg-green-500 shadow-[0_0_10px_green]" : "bg-gray-700"}`}
          style={{ width: `${(a / (h + a)) * 100}%` }}
        ></div>
      </div>
    </div>
  );
};

export default MatchDetailPage;
